const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/src/app.ts":"import \"express-async-errors\";\n\nimport express, { Request, Response, NextFunction } from \"express\";\nimport cors from \"cors\";\nimport helmet from \"helmet\";\nimport rateLimit from \"express-rate-limit\";\n\nconst authLimiter = rateLimit({\n  windowMs: 15 * 60 * 1000, // 15 minutes\n  max: 20, // 20 attempts per IP per 15 min\n  message: { success: false, message: \"Too many attempts. Try again in 15 minutes.\" },\n  standardHeaders: true,\n  legacyHeaders: false,\n});\n\nconst uploadLimiter = rateLimit({\n  windowMs: 60 * 1000, // 1 minute\n  max: 30, // 30 uploads per minute\n  message: { success: false, message: \"Upload rate limit reached. Slow down.\" },\n});\nimport compression from \"compression\";\nimport morgan from \"morgan\";\nimport cookieParser from \"cookie-parser\";\nimport path from \"path\";\n\n// Middleware\nimport { globalRateLimiter } from \"./middleware/rateLimiter\";\nimport { errorHandler } from \"./middleware/errorHandler\";\nimport { notFound } from \"./middleware/notFound\";\nimport { requestLogger } from \"./middleware/requestLogger\";\n\n// Core Routes\nimport authRoutes        from \"./routes/auth.routes\";\nimport storeRoutes       from \"./routes/store.routes\";\nimport productRoutes     from \"./routes/product.routes\";\nimport orderRoutes       from \"./routes/order.routes\";\nimport paymentRoutes     from \"./routes/payment.routes\";\nimport customerRoutes    from \"./routes/customer.routes\";\nimport adminRoutes       from \"./routes/admin.routes\";\nimport analyticsRoutes   from \"./routes/analytics.routes\";\nimport uploadRoutes      from \"./routes/upload.routes\";\nimport supportRoutes     from \"./routes/support.routes\";\nimport notificationRoutes from \"./routes/notification.routes\";\nimport couponRoutes      from \"./routes/coupon.routes\";\nimport discountRoutes    from \"./routes/discount.routes\";\nimport affiliateRoutes   from \"./routes/affiliate.routes\";\nimport aiRoutes          from \"./routes/ai.routes\";\nimport pushRoutes        from \"./routes/push.routes\";\nimport shippingRoutes    from \"./routes/shipping.routes\";\nimport reviewRoutes      from \"./routes/review.routes\";\nimport invoiceRoutes     from \"./routes/invoice.routes\";\nimport emailRoutes       from \"./routes/email.routes\";\nimport upsellRoutes      from \"./routes/upsell.routes\";\nimport abandonedCartRoutes from \"./routes/abandonedCart.routes\";\nimport notifSettingsRoutes from \"./routes/notificationSettings.routes\";\nimport virtualAccountRoutes from \"./routes/virtualAccount.routes\";\nimport whatsappRoutes    from \"./routes/whatsapp.routes\";\nimport deliveryRoutes    from \"./routes/delivery.routes\";\nimport currencyRoutes      from \"./routes/currency.routes\";\nimport supplierRoutes      from \"./routes/supplier.routes\";\nimport refundRoutes        from \"./routes/refund.routes\";\nimport giftCardRoutes      from \"./routes/giftCard.routes\";\nimport customerAccountRoutes from \"./routes/customerAccount.routes\";\nimport funnelRoutes        from \"./routes/funnel.routes\";\nimport apiKeyRoutes        from \"./routes/apiKey.routes\";\nimport webhookRoutes       from \"./routes/webhook.routes\";\nimport returnsRoutes       from \"./routes/returns.routes\";\nimport twoFARoutes         from \"./routes/twoFA.routes\";\nimport productSubscriptionRoutes from \"./routes/productSubscription.routes\";\nimport onboardingRoutes  from \"./routes/onboarding.routes\";\nimport milestoneRoutes   from \"./routes/milestone.routes\";\nimport contactRoutes     from \"./routes/contact.routes\";\nimport bundleRoutes      from \"./routes/bundle.routes\";\nimport groupBuyRoutes    from \"./routes/groupbuy.routes\";\nimport referralRoutes    from \"./routes/referral.routes\";\nimport navLevelRoutes    from \"./routes/navlevel.routes\";\nimport reportsRoutes     from \"./routes/reports.routes\";\nimport billingRoutes from \"./routes/billing.routes\";\nimport waitlistRoutes      from \"./routes/waitlist.routes\";\n\n// KAI CORE\nimport kaiRoutes from \"./routes/kai.routes\";\n\n// KAI EXPANSIONS\nimport kaiPowerRoutes from \"./routes/kai.power.routes\";\nimport featuresRoutes from \"./routes/features.routes\";\nimport loyaltyRoutes from \"./routes/loyalty.routes\";\nimport superchargeRoutes from \"./routes/supercharge.routes\";\nimport kaiAgentRoutes from \"./routes/kai.agent.routes\";\nimport themeRoutes from \"./routes/theme.routes\";\n\n// Controllers (Advanced AI + Automation)\nimport productIntelRoutes from \"./controllers/product.intel.controller\";\nimport intelRoutes from \"./controllers/kai.intelligence.controller\";\nimport fulfillmentRoutes from \"./controllers/fulfillment.controller\";\n\nconst app = express();\n\n// TRUST PROXY\nif (process.env.NODE_ENV === \"production\") {\n  app.set(\"trust proxy\", 1);\n}\n\n// SECURITY\napp.use(helmet({\n  crossOriginResourcePolicy: { policy: \"cross-origin\" },\n  contentSecurityPolicy: {\n    directives: {\n      defaultSrc: [\"'self'\"],\n      scriptSrc: [\"'self'\", \"https://js.stripe.com\"],\n      frameSrc: [\"'self'\", \"https://js.stripe.com\"],\n      connectSrc: [\"'self'\", \"https://api.stripe.com\"],\n      imgSrc: [\"'self'\", \"data:\", \"https:\"],\n      styleSrc: [\"'self'\", \"'unsafe-inline'\"],\n    },\n  },\n}));\n\n// CORS\nconst allowedOrigins = [\n  process.env.FRONTEND_URL || \"http://localhost:3000\",\n  \"http://localhost:3000\",\n  \"https://dropos-frontend1.vercel.app\",\n  \"https://droposhq.com\",\n  \"https://www.droposhq.com\",\n].filter(Boolean);\n\napp.use(cors({\n  origin: (origin, callback) => {\n    if (!origin || allowedOrigins.includes(origin) || origin.endsWith(\".vercel.app\")) {\n      callback(null, true);\n    } else {\n      callback(null, true);\n    }\n  },\n  credentials: true,\n}));\n\n// WEBHOOK RAW BODY\napp.use(\"/api/payments/webhook/stripe\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/paystack\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/flutterwave\", express.raw({ type: \"application/json\" }));\n\n// BODY PARSER\napp.use(express.json({ limit: \"50mb\" }));\napp.use(express.urlencoded({ extended: true, limit: \"50mb\" }));\napp.use(cookieParser());\napp.use(compression());\n\n// QUERY SANITIZATION\napp.use((req, _res, next) => {\n  for (const key in req.query) {\n    if (Array.isArray(req.query[key])) {\n      req.query[key] = (req.query[key] as string[]).at(-1) as any;\n    }\n  }\n  next();\n});\n\n// STATIC\napp.use(\"/uploads\", express.static(path.join(process.cwd(), \"uploads\")));\n\n// LOGGING\nif (process.env.NODE_ENV !== \"test\") {\n  app.use(morgan(\"combined\"));\n  app.use(requestLogger);\n}\n\n// RATE LIMIT\napp.use(\"/api\", globalRateLimiter);\n\n// HEALTH\napp.get(\"/api/health\", (_req: Request, res: Response) => {\n  res.json({ status: \"ok\", service: \"DropOS API\" });\n});\n\n// CORE BUSINESS ROUTES\napp.use(\"/api/auth\",                 authRoutes);\napp.use(\"/api/stores\",               storeRoutes);\napp.use(\"/api/products\",             productRoutes);\napp.use(\"/api/orders\",               orderRoutes);\napp.use(\"/api/payments\",             paymentRoutes);\napp.use(\"/api/customers\",            customerRoutes);\napp.use(\"/api/admin\",                adminRoutes);\napp.use(\"/api/analytics\",            analyticsRoutes);\napp.use(\"/api/upload\",               uploadRoutes);\napp.use(\"/api/support\",              supportRoutes);\napp.use(\"/api/notifications\",        notificationRoutes);\napp.use(\"/api/coupons\",              couponRoutes);\napp.use(\"/api/discounts\",            discountRoutes);\napp.use(\"/api/affiliates\",           affiliateRoutes);\napp.use(\"/api/ai\",                   aiRoutes);\napp.use(\"/api/push\",                 pushRoutes);\napp.use(\"/api/shipping\",             shippingRoutes);\napp.use(\"/api/reviews\",              reviewRoutes);\napp.use(\"/api/invoices\",             invoiceRoutes);\napp.use(\"/api/email\",                emailRoutes);\napp.use(\"/api/emails\",               emailRoutes); // alias for frontend\napp.use(\"/api/abandoned-carts\",      abandonedCartRoutes);\napp.use(\"/api/notification-settings\",notifSettingsRoutes);\napp.use(\"/api/currency\",             currencyRoutes);\napp.use(\"/api/suppliers\",            supplierRoutes);\napp.use(\"/api/refunds\",              refundRoutes);\napp.use(\"/api/gift-cards\",           giftCardRoutes);\napp.use(\"/api/customer-auth\",        customerAccountRoutes);\napp.use(\"/api/funnel\",               funnelRoutes);\napp.use(\"/api/api-keys\",             apiKeyRoutes);\napp.use(\"/api/webhooks\",             webhookRoutes);\napp.use(\"/api/ops\",                  returnsRoutes);\napp.use(\"/api/returns\",              returnsRoutes); // alias for frontend\napp.use(\"/api/2fa\",                  twoFARoutes);\napp.use(\"/api/product-subscriptions\",productSubscriptionRoutes);\napp.use(\"/api/upsell\",               upsellRoutes);\napp.use(\"/api/waitlist\",             waitlistRoutes);\n\n// KAI SYSTEM\n// SSE streaming needs special CORS handling\napp.options(\"/api/kai/smart-chat\", (req: any, res: any) => {\n  res.setHeader(\"Access-Control-Allow-Origin\", req.headers.origin || \"*\");\n  res.setHeader(\"Access-Control-Allow-Methods\", \"POST, OPTIONS\");\n  res.setHeader(\"Access-Control-Allow-Headers\", \"Content-Type, Authorization, Accept\");\n  res.status(204).send();\n});\napp.use(\"/api/kai\",              kaiRoutes);\napp.use(\"/api/billing\",          billingRoutes);\napp.use(\"/api/fulfillment\",       fulfillmentRoutes);\napp.use(\"/api/referral\",          referralRoutes);\napp.use(\"/api/intel\",             intelRoutes);\n\napp.use(\"/api/kai/power\",        kaiPowerRoutes);\napp.use(\"/api/kai/agent\",        kaiAgentRoutes);\napp.use(\"/api/features\",         featuresRoutes);\napp.use(\"/api/loyalty\",          loyaltyRoutes);\napp.use(\"/api/super\",            superchargeRoutes);\napp.use(\"/api/broadcasts\",       superchargeRoutes); // alias for frontend\napp.use(\"/api/theme\",            themeRoutes);\napp.use(\"/api/products/intel\",   productIntelRoutes);\napp.use(\"/api/intel\",            intelRoutes);\napp.use(\"/api/fulfillment\",      fulfillmentRoutes);\n\n// ERRORS\napp.use(\"/api/onboarding\",    onboardingRoutes);\napp.use(\"/api/milestones\",     milestoneRoutes);\napp.use(\"/api/contact\",        contactRoutes);\napp.use(\"/api/bundles\",        bundleRoutes);\napp.use(\"/api/group-buy\",      groupBuyRoutes);\napp.use(\"/api/nav-level\",      navLevelRoutes);\napp.use(\"/api/reports\",        reportsRoutes);\napp.use(\"/api/virtual-account\", virtualAccountRoutes);\napp.use(\"/api/whatsapp\",       whatsappRoutes);\napp.use(\"/api/delivery\",       deliveryRoutes);\n\n// ── New feature routes ─────────────────────────────────────────────────────────\nimport adsRoutes    from \"./routes/ads.routes\";\nimport domainRoutes from \"./routes/domain.routes\";\nimport bizGenRoutes from \"./routes/bizGen.routes\";\nimport bankRoutes   from \"./routes/bank.routes\";\n\napp.use(\"/api/ads\",     adsRoutes);\napp.use(\"/api/domains\", domainRoutes);\napp.use(\"/api/biz\",     bizGenRoutes);\napp.use(\"/api/banks\",   bankRoutes);\n\napp.use(notFound);\napp.use(errorHandler);\n\nexport default app;","frontend/src/app/dashboard/ads/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation, useQuery } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport { Sparkles, Copy, Check, RefreshCw, ExternalLink, Zap, Clock, TrendingUp } from \"lucide-react\";\n\nconst PLATFORMS = [\n  { id:\"tiktok\",    label:\"TikTok\",    emoji:\"🎵\", color:\"#000000\", grad:\"linear-gradient(135deg,#010101,#333)\" },\n  { id:\"instagram\", label:\"Instagram\", emoji:\"📸\", color:\"#E1306C\", grad:\"linear-gradient(135deg,#405DE6,#E1306C,#F77737)\" },\n  { id:\"facebook\",  label:\"Facebook\",  emoji:\"📘\", color:\"#1877F2\", grad:\"linear-gradient(135deg,#1877F2,#0d5fd4)\" },\n  { id:\"whatsapp\",  label:\"WhatsApp\",  emoji:\"💬\", color:\"#25D366\", grad:\"linear-gradient(135deg,#128C7E,#25D366)\" },\n];\n\nconst FORMATS = [\n  { id:\"video_script\", label:\"Video Script\", icon:\"🎬\", desc:\"30s hook + script + CTA\" },\n  { id:\"image_ad\",     label:\"Image Ad\",     icon:\"🖼️\", desc:\"Headline + copy + CTA\" },\n  { id:\"reel\",         label:\"Reel\",         icon:\"📱\", desc:\"15-30s reel format\" },\n  { id:\"story\",        label:\"Story\",        icon:\"⭕\", desc:\"Story with swipe-up\" },\n];\n\nconst GOALS = [\n  { id:\"sales\",       label:\"Drive Sales\",   emoji:\"💰\" },\n  { id:\"traffic\",     label:\"Get Traffic\",   emoji:\"🔗\" },\n  { id:\"awareness\",   label:\"Brand Awareness\",emoji:\"📣\" },\n  { id:\"engagement\",  label:\"Engagement\",    emoji:\"❤️\" },\n];\n\nexport default function AdsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n\n  const C = {\n    bg:     isDark ? \"#08051A\" : \"#F4F2FB\",\n    card:   isDark ? \"rgba(255,255,255,0.04)\" : \"#fff\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.5)\",\n    border: isDark ? \"rgba(107,53,232,0.15)\" : \"rgba(107,53,232,0.12)\",\n    input:  isDark ? \"rgba(255,255,255,0.06)\" : \"#fff\",\n  };\n\n  const [platform, setPlatform] = useState(\"tiktok\");\n  const [format,   setFormat]   = useState(\"video_script\");\n  const [goal,     setGoal]     = useState(\"sales\");\n  const [audience, setAudience] = useState(\"\");\n  const [budget,   setBudget]   = useState(\"\");\n  const [result,   setResult]   = useState<any>(null);\n  const [copied,   setCopied]   = useState<string|null>(null);\n\n  const copy = (text: string, key: string) => {\n    navigator.clipboard.writeText(text);\n    setCopied(key); setTimeout(() => setCopied(null), 2000);\n    toast.success(\"Copied to clipboard\");\n  };\n\n  const genMut = useMutation({\n    mutationFn: () => api.post(\"/ads/generate\", { storeId, platform, format, goal,\n      budget: budget ? Number(budget) : undefined, targetAudience: audience || undefined }),\n    onSuccess: (r) => { setResult(r.data.data); },\n    onError:   (e: any) => toast.error(e.response?.data?.error || \"Generation failed — check ANTHROPIC_API_KEY is set in Render\"),\n  });\n\n  const plat = PLATFORMS.find(p => p.id === platform)!;\n\n  const CopyBtn = ({ text, id }: { text: string; id: string }) => (\n    <button onClick={() => copy(text, id)}\n      style={{ display:\"flex\", alignItems:\"center\", gap:5, padding:\"5px 10px\", borderRadius:8,\n        background: copied===id ? \"rgba(16,185,129,0.1)\" : C.card,\n        border: `1px solid ${copied===id ? \"rgba(16,185,129,0.3)\" : C.border}`,\n        color: copied===id ? \"#10B981\" : C.muted, cursor:\"pointer\", fontSize:11, fontWeight:700, fontFamily:\"inherit\" }}>\n      {copied===id ? <Check size={11}/> : <Copy size={11}/>}\n      {copied===id ? \"Copied\" : \"Copy\"}\n    </button>\n  );\n\n  return (\n    <div style={{ maxWidth:960, margin:\"0 auto\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      {/* Header */}\n      <div style={{ marginBottom:28 }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:6 }}>\n          <div style={{ width:36, height:36, borderRadius:10, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <Sparkles size={16} color=\"#C4B5FD\"/>\n          </div>\n          <div>\n            <h1 style={{ fontSize:20, fontWeight:900, color:C.text, margin:0, letterSpacing:\"-0.03em\" }}>Ad Copy Generator</h1>\n            <p style={{ fontSize:12, color:C.muted, margin:0 }}>KIRO writes high-converting ads for your store</p>\n          </div>\n        </div>\n      </div>\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"340px 1fr\", gap:16 }} className=\"ads-layout\">\n        {/* LEFT — Config */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:12 }}>\n\n          {/* Platform */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:11, fontWeight:800, letterSpacing:\"0.1em\", color:C.muted, textTransform:\"uppercase\", margin:\"0 0 12px\" }}>Platform</p>\n            <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:8 }}>\n              {PLATFORMS.map(p => (\n                <button key={p.id} onClick={() => setPlatform(p.id)}\n                  style={{ padding:\"10px 12px\", borderRadius:12, border:`2px solid ${platform===p.id ? p.color : \"transparent\"}`,\n                    background: platform===p.id ? `${p.color}15` : \"rgba(255,255,255,0.03)\",\n                    cursor:\"pointer\", textAlign:\"left\", fontFamily:\"inherit\", transition:\"all 0.15s\" }}>\n                  <div style={{ display:\"flex\", alignItems:\"center\", gap:7 }}>\n                    <span style={{ fontSize:18 }}>{p.emoji}</span>\n                    <span style={{ fontSize:13, fontWeight:700, color:C.text }}>{p.label}</span>\n                  </div>\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Format */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:11, fontWeight:800, letterSpacing:\"0.1em\", color:C.muted, textTransform:\"uppercase\", margin:\"0 0 12px\" }}>Format</p>\n            <div style={{ display:\"flex\", flexDirection:\"column\", gap:6 }}>\n              {FORMATS.map(f => (\n                <button key={f.id} onClick={() => setFormat(f.id)}\n                  style={{ display:\"flex\", alignItems:\"center\", gap:10, padding:\"9px 12px\", borderRadius:10,\n                    border:`1px solid ${format===f.id ? \"rgba(107,53,232,0.4)\" : C.border}`,\n                    background: format===f.id ? \"rgba(107,53,232,0.08)\" : \"transparent\",\n                    cursor:\"pointer\", fontFamily:\"inherit\", transition:\"all 0.12s\" }}>\n                  <span style={{ fontSize:16 }}>{f.icon}</span>\n                  <div style={{ textAlign:\"left\" }}>\n                    <p style={{ fontSize:13, fontWeight:format===f.id?700:500, color:C.text, margin:0 }}>{f.label}</p>\n                    <p style={{ fontSize:11, color:C.muted, margin:0 }}>{f.desc}</p>\n                  </div>\n                  {format===f.id && <div style={{ marginLeft:\"auto\", width:6, height:6, borderRadius:\"50%\", background:\"#8B5CF6\" }}/>}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Goal */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:11, fontWeight:800, letterSpacing:\"0.1em\", color:C.muted, textTransform:\"uppercase\", margin:\"0 0 12px\" }}>Goal</p>\n            <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:6 }}>\n              {GOALS.map(g => (\n                <button key={g.id} onClick={() => setGoal(g.id)}\n                  style={{ padding:\"9px 10px\", borderRadius:10, border:`1px solid ${goal===g.id ? \"rgba(107,53,232,0.4)\" : C.border}`,\n                    background: goal===g.id ? \"rgba(107,53,232,0.08)\" : \"transparent\",\n                    cursor:\"pointer\", fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", gap:6 }}>\n                  <span>{g.emoji}</span>\n                  <span style={{ fontSize:12, fontWeight:goal===g.id?700:500, color:C.text }}>{g.label}</span>\n                </button>\n              ))}\n            </div>\n          </div>\n\n          {/* Optional */}\n          <div style={{ background:C.card, borderRadius:16, padding:18, border:`1px solid ${C.border}` }}>\n            <p style={{ fontSize:11, fontWeight:800, letterSpacing:\"0.1em\", color:C.muted, textTransform:\"uppercase\", margin:\"0 0 12px\" }}>Optional</p>\n            <div style={{ marginBottom:10 }}>\n              <label style={{ fontSize:12, fontWeight:600, color:C.muted, display:\"block\", marginBottom:5 }}>Target audience</label>\n              <input value={audience} onChange={e => setAudience(e.target.value)} placeholder=\"e.g. Nigerian women 22-35 who love fashion\"\n                style={{ width:\"100%\", padding:\"9px 12px\", borderRadius:10, border:`1px solid ${C.border}`, background:C.input, color:C.text, fontSize:12, fontFamily:\"inherit\", outline:\"none\" }}/>\n            </div>\n            <div>\n              <label style={{ fontSize:12, fontWeight:600, color:C.muted, display:\"block\", marginBottom:5 }}>Daily budget (₦)</label>\n              <input value={budget} onChange={e => setBudget(e.target.value)} type=\"number\" placeholder=\"e.g. 2000\"\n                style={{ width:\"100%\", padding:\"9px 12px\", borderRadius:10, border:`1px solid ${C.border}`, background:C.input, color:C.text, fontSize:12, fontFamily:\"inherit\", outline:\"none\" }}/>\n            </div>\n          </div>\n\n          <button onClick={() => { setResult(null); genMut.mutate(); }} disabled={genMut.isPending || !storeId}\n            style={{ padding:\"14px 0\", borderRadius:14, border:\"none\", cursor:\"pointer\",\n              background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\",\n              fontSize:15, fontWeight:800, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:10,\n              boxShadow:\"0 6px 24px rgba(107,53,232,0.35)\", opacity:genMut.isPending?0.7:1 }}>\n            {genMut.isPending ? <><RefreshCw size={16} style={{ animation:\"spin 0.7s linear infinite\" }}/> Writing your ad…</>\n              : <><Sparkles size={16}/> Generate Ad Copy</>}\n          </button>\n        </div>\n\n        {/* RIGHT — Result */}\n        <div>\n          <AnimatePresence mode=\"wait\">\n            {!result && !genMut.isPending && (\n              <motion.div key=\"empty\" initial={{ opacity:0 }} animate={{ opacity:1 }}\n                style={{ height:560, borderRadius:18, border:`2px dashed ${C.border}`, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", gap:14 }}>\n                <div style={{ width:64, height:64, borderRadius:18, background:\"rgba(107,53,232,0.08)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <Sparkles size={28} color=\"#8B5CF6\"/>\n                </div>\n                <div style={{ textAlign:\"center\" }}>\n                  <p style={{ fontSize:16, fontWeight:700, color:C.text, margin:\"0 0 6px\" }}>Ready to create</p>\n                  <p style={{ fontSize:13, color:C.muted }}>Pick your platform and format, then generate</p>\n                </div>\n                <div style={{ display:\"flex\", gap:8, flexWrap:\"wrap\", justifyContent:\"center\", maxWidth:280 }}>\n                  {[\"Hook in 3 seconds\",\"Nigerian market tone\",\"A/B test variants\",\"Targeting tips\"].map(t => (\n                    <span key={t} style={{ fontSize:11, padding:\"4px 10px\", borderRadius:99, background:C.card, border:`1px solid ${C.border}`, color:C.muted }}>\n                      ✓ {t}\n                    </span>\n                  ))}\n                </div>\n              </motion.div>\n            )}\n\n            {genMut.isPending && (\n              <motion.div key=\"loading\" initial={{ opacity:0 }} animate={{ opacity:1 }}\n                style={{ height:560, borderRadius:18, border:`1px solid ${C.border}`, background:C.card, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", gap:16 }}>\n                <div style={{ width:64, height:64, borderRadius:18, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", boxShadow:\"0 8px 32px rgba(107,53,232,0.4)\", animation:\"pulse 2s ease-in-out infinite\" }}>\n                  <Sparkles size={28} color=\"#C4B5FD\"/>\n                </div>\n                <div style={{ textAlign:\"center\" }}>\n                  <p style={{ fontSize:15, fontWeight:700, color:C.text, margin:\"0 0 6px\" }}>KIRO is writing your ad…</p>\n                  <p style={{ fontSize:13, color:C.muted }}>Researching market trends · Crafting hooks · ~15 seconds</p>\n                </div>\n              </motion.div>\n            )}\n\n            {result && (\n              <motion.div key=\"result\" initial={{ opacity:0, y:12 }} animate={{ opacity:1, y:0 }}\n                style={{ display:\"flex\", flexDirection:\"column\", gap:10 }}>\n                {/* Platform badge */}\n                <div style={{ display:\"flex\", alignItems:\"center\", gap:12, padding:\"12px 16px\", borderRadius:14, background:plat.grad, color:\"#fff\" }}>\n                  <span style={{ fontSize:22 }}>{plat.emoji}</span>\n                  <div style={{ flex:1 }}>\n                    <p style={{ fontSize:13, fontWeight:800, margin:0 }}>{plat.label} · {FORMATS.find(f=>f.id===format)?.label}</p>\n                    <p style={{ fontSize:11, margin:0, opacity:0.75 }}>\n                      {result.bestPostTime} · {result.estimatedReach}\n                    </p>\n                  </div>\n                  <a href={platform===\"tiktok\"?\"https://ads.tiktok.com/i18n/home\":platform===\"instagram\"||platform===\"facebook\"?\"https://business.facebook.com/adsmanager\":\"#\"}\n                    target=\"_blank\" rel=\"noreferrer\"\n                    style={{ display:\"flex\", alignItems:\"center\", gap:5, padding:\"6px 12px\", borderRadius:8, background:\"rgba(255,255,255,0.2)\", color:\"#fff\", textDecoration:\"none\", fontSize:12, fontWeight:700 }}>\n                    Post <ExternalLink size={11}/>\n                  </a>\n                </div>\n\n                {/* Hook */}\n                {result.hook && (\n                  <div style={{ padding:16, borderRadius:14, background:C.card, border:`1px solid ${C.border}` }}>\n                    <div style={{ display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginBottom:8 }}>\n                      <span style={{ fontSize:11, fontWeight:800, color:\"#8B5CF6\", letterSpacing:\"0.06em\" }}>🎣 HOOK</span>\n                      <CopyBtn text={result.hook} id=\"hook\"/>\n                    </div>\n                    <p style={{ fontSize:15, fontWeight:700, color:C.text, margin:0, lineHeight:1.5 }}>{result.hook}</p>\n                  </div>\n                )}\n\n                {/* Script */}\n                {result.script && (\n                  <div style={{ padding:16, borderRadius:14, background:C.card, border:`1px solid ${C.border}` }}>\n                    <div style={{ display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginBottom:8 }}>\n                      <span style={{ fontSize:11, fontWeight:800, color:\"#8B5CF6\", letterSpacing:\"0.06em\" }}>📝 SCRIPT</span>\n                      <CopyBtn text={result.script} id=\"script\"/>\n                    </div>\n                    <p style={{ fontSize:13, color:C.text, margin:0, lineHeight:1.7, whiteSpace:\"pre-line\", maxHeight:200, overflowY:\"auto\" }}>{result.script}</p>\n                  </div>\n                )}\n\n                {/* Caption */}\n                {result.caption && (\n                  <div style={{ padding:16, borderRadius:14, background:C.card, border:`1px solid ${C.border}` }}>\n                    <div style={{ display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginBottom:8 }}>\n                      <span style={{ fontSize:11, fontWeight:800, color:\"#8B5CF6\", letterSpacing:\"0.06em\" }}>📲 CAPTION</span>\n                      <CopyBtn text={result.caption} id=\"caption\"/>\n                    </div>\n                    <p style={{ fontSize:13, color:C.text, margin:0, lineHeight:1.65 }}>{result.caption}</p>\n                  </div>\n                )}\n\n                {/* CTA + Budget */}\n                <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:10 }}>\n                  {result.cta && (\n                    <div style={{ padding:14, borderRadius:14, background:C.card, border:`1px solid ${C.border}` }}>\n                      <div style={{ display:\"flex\", justifyContent:\"space-between\", marginBottom:6 }}>\n                        <span style={{ fontSize:11, fontWeight:800, color:\"#8B5CF6\" }}>👆 CTA</span>\n                        <CopyBtn text={result.cta} id=\"cta\"/>\n                      </div>\n                      <p style={{ fontSize:14, fontWeight:700, color:C.text, margin:0 }}>{result.cta}</p>\n                    </div>\n                  )}\n                  {result.aiBudgetTip && (\n                    <div style={{ padding:14, borderRadius:14, background:\"rgba(16,185,129,0.05)\", border:\"1px solid rgba(16,185,129,0.15)\" }}>\n                      <p style={{ fontSize:11, fontWeight:800, color:\"#10B981\", margin:\"0 0 6px\" }}>💡 BUDGET TIP</p>\n                      <p style={{ fontSize:12, color:C.text, margin:0, lineHeight:1.5 }}>{result.aiBudgetTip}</p>\n                    </div>\n                  )}\n                </div>\n\n                {/* A/B variants */}\n                {result.variations?.length > 0 && (\n                  <div style={{ padding:16, borderRadius:14, background:C.card, border:`1px solid ${C.border}` }}>\n                    <p style={{ fontSize:11, fontWeight:800, color:\"#8B5CF6\", margin:\"0 0 10px\" }}>🔀 A/B TEST HOOKS</p>\n                    {result.variations.map((v: string, i: number) => (\n                      <div key={i} style={{ display:\"flex\", gap:10, marginBottom:8, alignItems:\"flex-start\" }}>\n                        <span style={{ fontSize:11, fontWeight:800, color:\"#8B5CF6\", minWidth:16, marginTop:1 }}>{String.fromCharCode(65+i)}</span>\n                        <p style={{ fontSize:13, color:C.text, margin:0, flex:1, lineHeight:1.5 }}>{v}</p>\n                        <CopyBtn text={v} id={`v${i}`}/>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                {/* Targeting */}\n                {result.targetingTips?.length > 0 && (\n                  <div style={{ padding:16, borderRadius:14, background:C.card, border:`1px solid ${C.border}` }}>\n                    <p style={{ fontSize:11, fontWeight:800, color:\"#8B5CF6\", margin:\"0 0 10px\" }}>🎯 TARGETING TIPS</p>\n                    {result.targetingTips.map((tip: string, i: number) => (\n                      <div key={i} style={{ display:\"flex\", gap:8, marginBottom:6 }}>\n                        <TrendingUp size={11} color=\"#8B5CF6\" style={{ flexShrink:0, marginTop:2 }}/>\n                        <p style={{ fontSize:12, color:C.text, margin:0, lineHeight:1.5 }}>{tip}</p>\n                      </div>\n                    ))}\n                  </div>\n                )}\n\n                <button onClick={() => { setResult(null); }}\n                  style={{ padding:\"11px 0\", borderRadius:12, border:`1px solid ${C.border}`, background:\"transparent\", color:C.muted, fontSize:13, fontWeight:600, fontFamily:\"inherit\", cursor:\"pointer\" }}>\n                  Generate another\n                </button>\n              </motion.div>\n            )}\n          </AnimatePresence>\n        </div>\n      </div>\n\n      <style>{`\n        @keyframes spin{to{transform:rotate(360deg)}}\n        @keyframes pulse{0%,100%{box-shadow:0 8px 32px rgba(107,53,232,0.4)}50%{box-shadow:0 8px 48px rgba(107,53,232,0.6)}}\n        @media(max-width:768px){ .ads-layout{grid-template-columns:1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/domains/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation, useQuery } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport { Globe, Search, Check, Lock, ShoppingCart, RefreshCw, ChevronDown, Star, ExternalLink, Shield } from \"lucide-react\";\n\ntype Domain = { domain:string; available:boolean; ngn:number; usd:number; tld:string; popular?:boolean };\ntype Step = \"search\"|\"checkout\"|\"done\";\n\nexport default function DomainsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const user    = useAuthStore(s => s.user);\n  const storeId = user?.stores?.[0]?.id;\n\n  const C = {\n    card:   isDark ? \"rgba(255,255,255,0.04)\" : \"#fff\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.5)\",\n    border: isDark ? \"rgba(107,53,232,0.15)\" : \"rgba(107,53,232,0.12)\",\n    input:  isDark ? \"rgba(255,255,255,0.06)\" : \"#fff\",\n    faint:  isDark ? \"rgba(107,53,232,0.06)\" : \"rgba(107,53,232,0.04)\",\n  };\n\n  const inp: any = { width:\"100%\", padding:\"11px 14px\", borderRadius:11, border:`1px solid ${C.border}`, background:C.input, color:C.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" };\n\n  const [q, setQ]               = useState(\"\");\n  const [results, setResults]   = useState<Domain[]>([]);\n  const [selected, setSelected] = useState<Domain|null>(null);\n  const [step, setStep]         = useState<Step>(\"search\");\n  const [years, setYears]       = useState(1);\n  const [form, setForm]         = useState({ firstName:\"\", lastName:\"\", email:user?.email||\"\", phone:\"\", address:\"\", city:\"\", country:\"NG\" });\n\n  const { data: existingDomain } = useQuery({\n    queryKey: [\"store-domain\", storeId],\n    queryFn: () => api.get(`/domains/store/${storeId}`).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  const searchMut = useMutation({\n    mutationFn: () => api.get(\"/domains/search\", { params:{ q:q.trim() } }).then(r => r.data.data),\n    onSuccess: (data) => setResults(data || []),\n    onError: () => toast.error(\"Search failed\"),\n  });\n\n  const buyMut = useMutation({\n    mutationFn: () => api.post(\"/domains/register\", { storeId, domain:selected?.domain, years, ...form }),\n    onSuccess: () => setStep(\"done\"),\n    onError: (e: any) => toast.error(e.response?.data?.error || \"Purchase failed\"),\n  });\n\n  const canBuy = form.firstName && form.lastName && form.email && form.phone && form.address && form.city;\n\n  if (step === \"done\") return (\n    <div style={{ maxWidth:480, margin:\"80px auto 0\", textAlign:\"center\", padding:\"0 24px\" }}>\n      <motion.div initial={{ scale:0 }} animate={{ scale:1 }} transition={{ type:\"spring\", duration:0.5 }}>\n        <div style={{ width:72, height:72, borderRadius:\"50%\", background:\"rgba(16,185,129,0.12)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", margin:\"0 auto 20px\" }}>\n          <Check size={32} color=\"#10B981\"/>\n        </div>\n      </motion.div>\n      <h2 style={{ fontSize:24, fontWeight:900, color:C.text, margin:\"0 0 10px\", letterSpacing:\"-0.04em\" }}>Domain registered! 🎉</h2>\n      <p style={{ fontSize:14, color:C.muted, margin:\"0 0 6px\" }}>\n        <strong style={{ color:C.text }}>{selected?.domain}</strong> is yours.\n      </p>\n      <p style={{ fontSize:13, color:C.muted, margin:\"0 0 28px\", lineHeight:1.65 }}>\n        DNS is being configured to point to your store automatically. Live within 24-48 hours.\n      </p>\n      <div style={{ display:\"flex\", gap:10, justifyContent:\"center\" }}>\n        <button onClick={() => { setStep(\"search\"); setResults([]); setQ(\"\"); setSelected(null); }}\n          style={{ padding:\"11px 22px\", borderRadius:12, border:`1px solid ${C.border}`, background:C.card, color:C.text, cursor:\"pointer\", fontSize:14, fontWeight:600, fontFamily:\"inherit\" }}>\n          Buy another\n        </button>\n      </div>\n    </div>\n  );\n\n  return (\n    <div style={{ maxWidth:760, margin:\"0 auto\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      {/* Header */}\n      <div style={{ display:\"flex\", alignItems:\"center\", gap:12, marginBottom:24 }}>\n        <div style={{ width:40, height:40, borderRadius:12, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n          <Globe size={18} color=\"#C4B5FD\"/>\n        </div>\n        <div>\n          <h1 style={{ fontSize:20, fontWeight:900, color:C.text, margin:0, letterSpacing:\"-0.03em\" }}>Domain Manager</h1>\n          <p style={{ fontSize:12, color:C.muted, margin:0 }}>Buy a domain and connect it to your store — automatic DNS setup</p>\n        </div>\n      </div>\n\n      {/* Connected domain */}\n      {existingDomain?.customDomain && (\n        <div style={{ padding:\"14px 18px\", borderRadius:14, background:\"rgba(16,185,129,0.05)\", border:\"1px solid rgba(16,185,129,0.15)\", display:\"flex\", alignItems:\"center\", gap:12, marginBottom:20 }}>\n          <Check size={16} color=\"#10B981\"/>\n          <div style={{ flex:1 }}>\n            <p style={{ fontSize:13, fontWeight:700, color:\"#10B981\", margin:0 }}>Connected: {existingDomain.customDomain}</p>\n            <p style={{ fontSize:11, color:C.muted, margin:0 }}>Your store is live at this domain</p>\n          </div>\n          <a href={`https://${existingDomain.customDomain}`} target=\"_blank\" rel=\"noreferrer\" style={{ color:\"#10B981\", textDecoration:\"none\" }}>\n            <ExternalLink size={14}/>\n          </a>\n        </div>\n      )}\n\n      <AnimatePresence mode=\"wait\">\n        {step === \"search\" && (\n          <motion.div key=\"search\" initial={{ opacity:0 }} animate={{ opacity:1 }}>\n            {/* Search */}\n            <div style={{ background:C.card, borderRadius:20, padding:24, border:`1px solid ${C.border}`, marginBottom:16 }}>\n              <div style={{ display:\"flex\", gap:10 }}>\n                <div style={{ flex:1, display:\"flex\", alignItems:\"center\", gap:10, padding:\"13px 16px\", borderRadius:14, border:`1px solid ${q ? \"rgba(107,53,232,0.4)\" : C.border}`, background:C.input, transition:\"border 0.15s\" }}>\n                  <Globe size={16} color={C.muted as string}/>\n                  <input value={q} onChange={e => setQ(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,\"\"))}\n                    placeholder=\"Search for your perfect domain…\"\n                    onKeyDown={e => { if (e.key===\"Enter\" && q.trim()) searchMut.mutate(); }}\n                    style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", color:C.text, fontSize:14, fontFamily:\"inherit\" }}/>\n                </div>\n                <button onClick={() => searchMut.mutate()} disabled={!q.trim() || searchMut.isPending}\n                  style={{ padding:\"13px 22px\", borderRadius:14, border:\"none\", cursor:\"pointer\",\n                    background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\",\n                    fontSize:14, fontWeight:700, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", gap:8,\n                    opacity:!q.trim()?0.5:1, boxShadow:\"0 4px 16px rgba(107,53,232,0.25)\" }}>\n                  {searchMut.isPending ? <RefreshCw size={14} style={{ animation:\"spin 0.7s linear infinite\" }}/> : <Search size={14}/>}\n                  Search\n                </button>\n              </div>\n              <p style={{ fontSize:12, color:C.muted, margin:\"10px 0 0\", textAlign:\"center\" }}>\n                Try your brand name — we'll check .com, .store, .shop, .ng and more\n              </p>\n            </div>\n\n            {/* Results */}\n            {results.length > 0 && (\n              <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }}\n                style={{ background:C.card, borderRadius:20, border:`1px solid ${C.border}`, overflow:\"hidden\" }}>\n                {results.map((r, i) => (\n                  <div key={r.domain} style={{ display:\"flex\", alignItems:\"center\", gap:14, padding:\"14px 20px\",\n                    borderBottom: i < results.length-1 ? `1px solid rgba(255,255,255,0.04)` : \"none\",\n                    opacity: r.available ? 1 : 0.45 }}>\n                    <div style={{ flex:1 }}>\n                      <div style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n                        <p style={{ fontSize:15, fontWeight:700, color:C.text, margin:0 }}>{r.domain}</p>\n                        {r.popular && (\n                          <span style={{ fontSize:9, fontWeight:800, color:\"#F59E0B\", background:\"rgba(245,158,11,0.12)\", padding:\"2px 7px\", borderRadius:99, display:\"flex\", alignItems:\"center\", gap:3 }}>\n                            <Star size={8} fill=\"#F59E0B\"/> POPULAR\n                          </span>\n                        )}\n                        {!r.available && <span style={{ fontSize:10, color:C.muted, background:C.faint, padding:\"2px 8px\", borderRadius:99 }}>Taken</span>}\n                      </div>\n                    </div>\n                    <div style={{ textAlign:\"right\", minWidth:90 }}>\n                      <p style={{ fontSize:15, fontWeight:800, color:r.available?C.text:C.muted, margin:0 }}>₦{r.ngn?.toLocaleString()}</p>\n                      <p style={{ fontSize:10, color:C.muted, margin:0 }}>per year</p>\n                    </div>\n                    {r.available ? (\n                      <button onClick={() => { setSelected(r); setStep(\"checkout\"); }}\n                        style={{ padding:\"8px 18px\", borderRadius:10, border:\"none\", cursor:\"pointer\",\n                          background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\",\n                          fontSize:13, fontWeight:700, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", gap:6 }}>\n                        <ShoppingCart size={12}/> Buy\n                      </button>\n                    ) : (\n                      <div style={{ width:68, height:34, borderRadius:10, background:C.faint, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                        <Lock size={13} color={C.muted as string}/>\n                      </div>\n                    )}\n                  </div>\n                ))}\n              </motion.div>\n            )}\n\n            {/* Features */}\n            {results.length === 0 && (\n              <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:12, marginTop:20 }} className=\"feat-grid\">\n                {[\n                  { icon:\"🔒\", title:\"Instant DNS setup\",    desc:\"Automatically points to your DropOS store. No technical setup.\" },\n                  { icon:\"₦\",  title:\"Pay in Naira\",         desc:\"No dollar card needed. Pay through Paystack.\" },\n                  { icon:\"🔄\", title:\"Auto-renewal alerts\",  desc:\"We remind you before it expires. Never lose your domain.\" },\n                ].map(f => (\n                  <div key={f.title} style={{ padding:16, borderRadius:14, background:C.card, border:`1px solid ${C.border}`, textAlign:\"center\" }}>\n                    <p style={{ fontSize:24, margin:\"0 0 8px\" }}>{f.icon}</p>\n                    <p style={{ fontSize:13, fontWeight:700, color:C.text, margin:\"0 0 4px\" }}>{f.title}</p>\n                    <p style={{ fontSize:11, color:C.muted, margin:0, lineHeight:1.5 }}>{f.desc}</p>\n                  </div>\n                ))}\n              </div>\n            )}\n          </motion.div>\n        )}\n\n        {step === \"checkout\" && selected && (\n          <motion.div key=\"checkout\" initial={{ opacity:0, x:20 }} animate={{ opacity:1, x:0 }}>\n            <button onClick={() => setStep(\"search\")} style={{ fontSize:12, color:C.muted, background:\"none\", border:\"none\", cursor:\"pointer\", fontFamily:\"inherit\", marginBottom:16, display:\"flex\", alignItems:\"center\", gap:6 }}>\n              ← Back to search\n            </button>\n\n            {/* Summary */}\n            <div style={{ padding:20, borderRadius:18, background:\"linear-gradient(135deg,rgba(107,53,232,0.1),rgba(107,53,232,0.05))\", border:`1px solid rgba(107,53,232,0.2)`, marginBottom:16 }}>\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:14 }}>\n                <div style={{ width:44, height:44, borderRadius:13, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <Globe size={20} color=\"#C4B5FD\"/>\n                </div>\n                <div style={{ flex:1 }}>\n                  <p style={{ fontSize:20, fontWeight:900, color:C.text, margin:0, letterSpacing:\"-0.03em\" }}>{selected.domain}</p>\n                  <p style={{ fontSize:12, color:C.muted, margin:\"2px 0 0\" }}>Will auto-connect to your DropOS store</p>\n                </div>\n                <div style={{ display:\"flex\", gap:6 }}>\n                  {[1,2,3].map(y => (\n                    <button key={y} onClick={() => setYears(y)}\n                      style={{ padding:\"5px 12px\", borderRadius:8, border:`1px solid ${years===y?\"rgba(107,53,232,0.4)\":C.border}`, background:years===y?\"rgba(107,53,232,0.12)\":\"transparent\", color:years===y?\"#A78BFA\":C.muted, cursor:\"pointer\", fontSize:12, fontWeight:700, fontFamily:\"inherit\" }}>\n                      {y}yr\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            {/* Form */}\n            <div style={{ background:C.card, borderRadius:18, padding:22, border:`1px solid ${C.border}`, marginBottom:14 }}>\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:8, marginBottom:18 }}>\n                <Shield size={14} color=\"#8B5CF6\"/>\n                <p style={{ fontSize:13, fontWeight:700, color:C.text, margin:0 }}>Registration details</p>\n                <span style={{ fontSize:11, color:C.muted, marginLeft:\"auto\" }}>Required by ICANN</span>\n              </div>\n              <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }} className=\"form-cols\">\n                <div>\n                  <label style={{ fontSize:11, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>First name *</label>\n                  <input value={form.firstName} onChange={e=>setForm(f=>({...f,firstName:e.target.value}))} style={inp} placeholder=\"Olamide\"/>\n                </div>\n                <div>\n                  <label style={{ fontSize:11, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>Last name *</label>\n                  <input value={form.lastName} onChange={e=>setForm(f=>({...f,lastName:e.target.value}))} style={inp} placeholder=\"Sotunde\"/>\n                </div>\n                <div style={{ gridColumn:\"1/-1\" }}>\n                  <label style={{ fontSize:11, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>Email *</label>\n                  <input type=\"email\" value={form.email} onChange={e=>setForm(f=>({...f,email:e.target.value}))} style={inp}/>\n                </div>\n                <div>\n                  <label style={{ fontSize:11, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>Phone *</label>\n                  <input value={form.phone} onChange={e=>setForm(f=>({...f,phone:e.target.value}))} style={inp} placeholder=\"+2348012345678\"/>\n                </div>\n                <div>\n                  <label style={{ fontSize:11, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>City *</label>\n                  <input value={form.city} onChange={e=>setForm(f=>({...f,city:e.target.value}))} style={inp} placeholder=\"Lagos\"/>\n                </div>\n                <div style={{ gridColumn:\"1/-1\" }}>\n                  <label style={{ fontSize:11, fontWeight:700, color:C.muted, display:\"block\", marginBottom:5 }}>Address *</label>\n                  <input value={form.address} onChange={e=>setForm(f=>({...f,address:e.target.value}))} style={inp} placeholder=\"123 Anywhere Street, Victoria Island\"/>\n                </div>\n              </div>\n            </div>\n\n            {/* Total */}\n            <div style={{ padding:\"16px 20px\", borderRadius:14, background:C.faint, border:`1px solid ${C.border}`, display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:12 }}>\n              <div>\n                <p style={{ fontSize:11, color:C.muted, margin:0 }}>{years} year registration</p>\n                <p style={{ fontSize:24, fontWeight:900, color:C.text, margin:0, letterSpacing:\"-0.04em\" }}>₦{((selected.ngn||0)*years).toLocaleString()}</p>\n              </div>\n              <div style={{ fontSize:12, color:\"#10B981\", background:\"rgba(16,185,129,0.08)\", padding:\"6px 14px\", borderRadius:99, fontWeight:700 }}>\n                ✅ DNS auto-configured\n              </div>\n            </div>\n\n            <button onClick={() => buyMut.mutate()} disabled={!canBuy || buyMut.isPending}\n              style={{ width:\"100%\", padding:\"15px 0\", borderRadius:14, border:\"none\", cursor:\"pointer\",\n                background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\",\n                fontSize:15, fontWeight:800, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:10,\n                opacity:(!canBuy)?0.5:1, boxShadow:\"0 6px 24px rgba(107,53,232,0.3)\" }}>\n              {buyMut.isPending ? <><RefreshCw size={15} style={{ animation:\"spin 0.7s linear infinite\" }}/> Registering…</>\n                : <><ShoppingCart size={15}/> Purchase · ₦{((selected.ngn||0)*years).toLocaleString()}</>}\n            </button>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        @keyframes spin{to{transform:rotate(360deg)}}\n        @media(max-width:640px){ .feat-grid{grid-template-columns:1fr!important;} .form-cols{grid-template-columns:1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/start-business/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport toast from \"react-hot-toast\";\nimport { Sparkles, Zap, Check, RefreshCw, ArrowRight, Package, TrendingUp, Store, ChevronRight } from \"lucide-react\";\n\nconst NICHES = [\n  { emoji:\"👗\", label:\"Fashion\"         },\n  { emoji:\"📱\", label:\"Phone Accessories\"},\n  { emoji:\"💄\", label:\"Beauty & Skincare\"},\n  { emoji:\"🏠\", label:\"Home & Kitchen\"  },\n  { emoji:\"💪\", label:\"Fitness\"         },\n  { emoji:\"👶\", label:\"Baby Products\"   },\n  { emoji:\"🎮\", label:\"Gadgets\"         },\n  { emoji:\"🌿\", label:\"Health\"          },\n  { emoji:\"🐾\", label:\"Pet Supplies\"    },\n  { emoji:\"🎒\", label:\"Bags\"            },\n  { emoji:\"🛒\", label:\"General Store\"  },\n  { emoji:\"✨\", label:\"Surprise me!\"    },\n];\n\ntype Step = \"input\"|\"generating\"|\"result\"|\"launching\"|\"done\";\n\nexport default function StartBusinessPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const user    = useAuthStore(s => s.user);\n  const storeId = user?.stores?.[0]?.id;\n\n  const C = {\n    card:   isDark ? \"rgba(255,255,255,0.04)\" : \"#fff\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.5)\",\n    border: isDark ? \"rgba(107,53,232,0.15)\" : \"rgba(107,53,232,0.12)\",\n    faint:  isDark ? \"rgba(107,53,232,0.06)\" : \"rgba(107,53,232,0.04)\",\n    input:  isDark ? \"rgba(255,255,255,0.06)\" : \"#fff\",\n  };\n\n  const [step, setStep]       = useState<Step>(\"input\");\n  const [interest, setInterest] = useState(\"\");\n  const [budget, setBudget]   = useState(\"\");\n  const [experience, setExp]  = useState<\"none\"|\"some\"|\"experienced\">(\"none\");\n  const [biz, setBiz]         = useState<any>(null);\n  const [launched, setLaunched] = useState<any>(null);\n\n  const genMut = useMutation({\n    mutationFn: () => api.post(\"/biz/generate\", { interest, budget:budget?Number(budget):undefined, experience }),\n    onSuccess: (r) => { setBiz(r.data.data); setStep(\"result\"); },\n    onError: (e:any) => { toast.error(e.response?.data?.error || \"Generation failed\"); setStep(\"input\"); },\n  });\n\n  const launchMut = useMutation({\n    mutationFn: async () => {\n      await api.post(`/biz/apply/${storeId}`, { business:biz });\n      const r = await api.post(`/biz/import-products/${storeId}`, { products:biz.suggestedProducts });\n      return r.data.data;\n    },\n    onSuccess: (data) => { setLaunched(data); setStep(\"done\"); },\n    onError: (e:any) => toast.error(e.response?.data?.error || \"Launch failed\"),\n  });\n\n  const handleGenerate = () => { setStep(\"generating\"); genMut.mutate(); };\n\n  // DONE\n  if (step === \"done\") return (\n    <div style={{ maxWidth:520, margin:\"60px auto 0\", textAlign:\"center\", padding:\"0 24px\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <motion.div initial={{ scale:0 }} animate={{ scale:1 }} transition={{ type:\"spring\", stiffness:200 }}>\n        <div style={{ width:80, height:80, borderRadius:24, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", margin:\"0 auto 20px\", boxShadow:\"0 16px 48px rgba(107,53,232,0.4)\" }}>\n          <Zap size={36} color=\"#C4B5FD\"/>\n        </div>\n      </motion.div>\n      <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.3 }}>\n        <h2 style={{ fontSize:28, fontWeight:900, color:C.text, margin:\"0 0 10px\", letterSpacing:\"-0.04em\" }}>\n          {biz?.storeName} is live! 🚀\n        </h2>\n        <p style={{ fontSize:15, color:C.muted, margin:\"0 0 6px\" }}>\n          Your store is set up with {launched?.created || 0} products.\n        </p>\n        <p style={{ fontSize:14, color:\"#10B981\", fontWeight:700, margin:\"0 0 32px\" }}>\n          ✅ Store identity applied · Products imported · Ready to sell\n        </p>\n        <div style={{ display:\"flex\", gap:12, justifyContent:\"center\", flexWrap:\"wrap\" }}>\n          <a href=\"/dashboard\" style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"13px 24px\", borderRadius:12, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\", textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 6px 20px rgba(107,53,232,0.25)\" }}>\n            <TrendingUp size={14}/> Go to dashboard\n          </a>\n          <a href=\"/dashboard/products\" style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"13px 24px\", borderRadius:12, border:`1px solid ${C.border}`, background:C.card, color:C.text, textDecoration:\"none\", fontSize:14, fontWeight:600 }}>\n            <Package size={14}/> View products <ChevronRight size={13}/>\n          </a>\n        </div>\n      </motion.div>\n    </div>\n  );\n\n  return (\n    <div style={{ maxWidth:800, margin:\"0 auto\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <div style={{ display:\"flex\", alignItems:\"center\", gap:12, marginBottom:28 }}>\n        <div style={{ width:40, height:40, borderRadius:12, background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n          <Sparkles size={18} color=\"#C4B5FD\"/>\n        </div>\n        <div>\n          <h1 style={{ fontSize:20, fontWeight:900, color:C.text, margin:0, letterSpacing:\"-0.03em\" }}>Start a Business</h1>\n          <p style={{ fontSize:12, color:C.muted, margin:0 }}>KIRO picks a niche, finds products, and sets up your entire store</p>\n        </div>\n      </div>\n\n      <AnimatePresence mode=\"wait\">\n        {/* INPUT */}\n        {step === \"input\" && (\n          <motion.div key=\"input\" initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}>\n            <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:16, marginBottom:16 }} className=\"biz-split\">\n              {/* Niche picker */}\n              <div style={{ background:C.card, borderRadius:18, padding:22, border:`1px solid ${C.border}` }}>\n                <p style={{ fontSize:13, fontWeight:800, color:C.text, margin:\"0 0 14px\" }}>What do you want to sell?</p>\n                <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr 1fr\", gap:6, marginBottom:14 }}>\n                  {NICHES.map(n => {\n                    const active = interest === n.label;\n                    return (\n                      <button key={n.label} onClick={() => setInterest(active?\"\":n.label)}\n                        style={{ padding:\"8px 6px\", borderRadius:10, border:`1px solid ${active?\"rgba(107,53,232,0.5)\":\"transparent\"}`, background:active?\"rgba(107,53,232,0.1)\":C.faint, cursor:\"pointer\", fontFamily:\"inherit\", textAlign:\"center\", transition:\"all 0.12s\" }}>\n                        <p style={{ fontSize:18, margin:\"0 0 2px\" }}>{n.emoji}</p>\n                        <p style={{ fontSize:10, fontWeight:active?700:500, color:active?\"#A78BFA\":C.muted, margin:0, lineHeight:1.2 }}>{n.label}</p>\n                      </button>\n                    );\n                  })}\n                </div>\n                <textarea value={interest} onChange={e => setInterest(e.target.value)} rows={2}\n                  placeholder=\"Or describe what you're interested in…\"\n                  style={{ width:\"100%\", padding:\"10px 12px\", borderRadius:10, border:`1px solid ${C.border}`, background:C.input, color:C.text, fontSize:12, fontFamily:\"inherit\", outline:\"none\", resize:\"none\" }}/>\n              </div>\n\n              {/* Budget + experience */}\n              <div style={{ display:\"flex\", flexDirection:\"column\", gap:12 }}>\n                <div style={{ background:C.card, borderRadius:18, padding:22, border:`1px solid ${C.border}` }}>\n                  <p style={{ fontSize:13, fontWeight:800, color:C.text, margin:\"0 0 14px\" }}>Starting budget</p>\n                  <div style={{ position:\"relative\", marginBottom:8 }}>\n                    <span style={{ position:\"absolute\", left:13, top:\"50%\", transform:\"translateY(-50%)\", fontSize:14, fontWeight:700, color:C.muted }}>₦</span>\n                    <input type=\"number\" value={budget} onChange={e => setBudget(e.target.value)} placeholder=\"50,000\"\n                      style={{ width:\"100%\", padding:\"11px 14px 11px 30px\", borderRadius:11, border:`1px solid ${C.border}`, background:C.input, color:C.text, fontSize:14, fontFamily:\"inherit\", outline:\"none\" }}/>\n                  </div>\n                  <p style={{ fontSize:11, color:C.muted, margin:0 }}>KIRO picks products you can afford to start with</p>\n                </div>\n\n                <div style={{ background:C.card, borderRadius:18, padding:22, border:`1px solid ${C.border}`, flex:1 }}>\n                  <p style={{ fontSize:13, fontWeight:800, color:C.text, margin:\"0 0 14px\" }}>Your experience</p>\n                  {([ [\"none\",\"Brand new to this 👋\"], [\"some\",\"Tried before 🔄\"], [\"experienced\",\"I know what I'm doing ✅\"] ] as any[]).map(([id, label]: any) => (\n                    <button key={id} onClick={() => setExp(id)}\n                      style={{ display:\"flex\", alignItems:\"center\", gap:9, width:\"100%\", padding:\"9px 12px\", borderRadius:10, border:`1px solid ${experience===id?\"rgba(107,53,232,0.3)\":\"transparent\"}`, background:experience===id?\"rgba(107,53,232,0.07)\":\"transparent\", cursor:\"pointer\", fontFamily:\"inherit\", marginBottom:6, transition:\"all 0.12s\" }}>\n                      <div style={{ width:16, height:16, borderRadius:\"50%\", border:`2px solid ${experience===id?\"#6B35E8\":C.border}`, background:experience===id?\"#6B35E8\":\"transparent\", flexShrink:0, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                        {experience===id && <div style={{ width:6, height:6, borderRadius:\"50%\", background:\"#fff\" }}/>}\n                      </div>\n                      <span style={{ fontSize:12, fontWeight:experience===id?700:500, color:experience===id?C.text:C.muted }}>{label}</span>\n                    </button>\n                  ))}\n                </div>\n              </div>\n            </div>\n\n            <button onClick={handleGenerate}\n              style={{ width:\"100%\", padding:\"16px 0\", borderRadius:16, border:\"none\", cursor:\"pointer\", background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\", fontSize:16, fontWeight:800, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:12, boxShadow:\"0 8px 32px rgba(107,53,232,0.35)\" }}>\n              <Sparkles size={18}/> Build my business with KIRO\n            </button>\n          </motion.div>\n        )}\n\n        {/* GENERATING */}\n        {step === \"generating\" && (\n          <motion.div key=\"gen\" initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}\n            style={{ textAlign:\"center\", padding:\"80px 24px\" }}>\n            <div style={{ width:88, height:88, borderRadius:26, background:\"linear-gradient(145deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", margin:\"0 auto 24px\", boxShadow:\"0 16px 56px rgba(107,53,232,0.5)\", animation:\"pulse 2s ease-in-out infinite\" }}>\n              <Sparkles size={40} color=\"#C4B5FD\"/>\n            </div>\n            <h2 style={{ fontSize:22, fontWeight:800, color:C.text, margin:\"0 0 10px\", letterSpacing:\"-0.03em\" }}>KIRO is building your business…</h2>\n            <p style={{ fontSize:14, color:C.muted, lineHeight:1.6, margin:\"0 auto\", maxWidth:360 }}>\n              Researching the Nigerian market · Picking a profitable niche · Selecting 12 winning products\n            </p>\n          </motion.div>\n        )}\n\n        {/* RESULT */}\n        {step === \"result\" && biz && (\n          <motion.div key=\"result\" initial={{ opacity:0, y:12 }} animate={{ opacity:1, y:0 }} exit={{ opacity:0 }}>\n            {/* Business card */}\n            <div style={{ borderRadius:20, overflow:\"hidden\", marginBottom:16, border:`1px solid ${biz.primaryColor}30` }}>\n              <div style={{ padding:24, background:`linear-gradient(135deg,${biz.primaryColor}15,${biz.primaryColor}06)` }}>\n                <div style={{ display:\"flex\", alignItems:\"flex-start\", gap:16, marginBottom:18 }}>\n                  <div style={{ width:56, height:56, borderRadius:16, background:biz.primaryColor, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, boxShadow:`0 8px 24px ${biz.primaryColor}50` }}>\n                    <Store size={26} color=\"#fff\"/>\n                  </div>\n                  <div style={{ flex:1 }}>\n                    <h2 style={{ fontSize:26, fontWeight:900, color:C.text, margin:\"0 0 4px\", letterSpacing:\"-0.04em\" }}>{biz.storeName}</h2>\n                    <p style={{ fontSize:14, fontWeight:700, color:biz.primaryColor, margin:\"0 0 6px\" }}>{biz.tagline}</p>\n                    <p style={{ fontSize:13, color:C.muted, margin:0, lineHeight:1.5 }}>{biz.description}</p>\n                  </div>\n                </div>\n                <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:10 }}>\n                  {[\n                    { label:\"Niche\", value:biz.niche },\n                    { label:\"Products\", value:`${biz.suggestedProducts?.length} ready` },\n                    { label:\"Est. profit\", value:biz.estimatedProfit, color:\"#10B981\" },\n                  ].map(s => (\n                    <div key={s.label} style={{ padding:14, borderRadius:12, background:C.card, border:`1px solid ${C.border}`, textAlign:\"center\" }}>\n                      <p style={{ fontSize:11, color:C.muted, margin:\"0 0 4px\" }}>{s.label}</p>\n                      <p style={{ fontSize:13, fontWeight:700, color:s.color||C.text, margin:0 }}>{s.value}</p>\n                    </div>\n                  ))}\n                </div>\n              </div>\n              <div style={{ padding:\"14px 24px\", background:C.card, borderTop:`1px solid ${biz.primaryColor}20` }}>\n                <p style={{ fontSize:11, fontWeight:700, color:C.muted, margin:\"0 0 4px\", textTransform:\"uppercase\", letterSpacing:\"0.08em\" }}>Why KIRO chose this</p>\n                <p style={{ fontSize:13, color:C.muted, margin:0, lineHeight:1.6 }}>{biz.whyThisNiche}</p>\n              </div>\n            </div>\n\n            {/* Products list */}\n            <div style={{ background:C.card, borderRadius:18, border:`1px solid ${C.border}`, overflow:\"hidden\", marginBottom:16 }}>\n              <div style={{ padding:\"14px 20px\", borderBottom:`1px solid ${C.border}`, display:\"flex\", alignItems:\"center\", gap:10 }}>\n                <Package size={15} color=\"#8B5CF6\"/>\n                <p style={{ fontSize:14, fontWeight:700, color:C.text, margin:0 }}>{biz.suggestedProducts?.length} products selected by KIRO</p>\n                <span style={{ marginLeft:\"auto\", fontSize:11, color:\"#10B981\", background:\"rgba(16,185,129,0.1)\", padding:\"2px 10px\", borderRadius:99, fontWeight:700 }}>Ready to import</span>\n              </div>\n              <div style={{ maxHeight:280, overflowY:\"auto\" }}>\n                {biz.suggestedProducts?.map((p: any, i: number) => (\n                  <div key={i} style={{ display:\"flex\", alignItems:\"center\", gap:12, padding:\"11px 20px\", borderBottom:`1px solid rgba(255,255,255,0.04)` }}>\n                    <div style={{ width:34, height:34, borderRadius:9, background:C.faint, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n                      <Package size={14} color=\"#8B5CF6\"/>\n                    </div>\n                    <div style={{ flex:1, minWidth:0 }}>\n                      <p style={{ fontSize:13, fontWeight:600, color:C.text, margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{p.name}</p>\n                      <p style={{ fontSize:11, color:C.muted, margin:0 }}>{p.why}</p>\n                    </div>\n                    <div style={{ textAlign:\"right\", flexShrink:0 }}>\n                      <p style={{ fontSize:13, fontWeight:800, color:C.text, margin:0 }}>₦{p.targetPrice?.toLocaleString()}</p>\n                      <p style={{ fontSize:10, fontWeight:700, color:\"#10B981\", margin:0 }}>{p.margin}% margin</p>\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </div>\n\n            {/* Actions */}\n            <div style={{ display:\"flex\", gap:12 }}>\n              <button onClick={() => launchMut.mutate()} disabled={launchMut.isPending || !storeId}\n                style={{ flex:2, padding:\"15px 0\", borderRadius:14, border:\"none\", cursor:\"pointer\", background:\"linear-gradient(135deg,#2D1B69,#6B35E8)\", color:\"#fff\", fontSize:15, fontWeight:800, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:10, boxShadow:\"0 8px 32px rgba(107,53,232,0.3)\", opacity:launchMut.isPending?0.7:1 }}>\n                {launchMut.isPending ? <><RefreshCw size={15} style={{ animation:\"spin 0.7s linear infinite\" }}/> Launching…</>\n                  : <><Zap size={15}/> Launch this business</>}\n              </button>\n              <button onClick={() => { setBiz(null); setStep(\"input\"); }}\n                style={{ flex:1, padding:\"15px 0\", borderRadius:14, border:`1px solid ${C.border}`, background:C.card, color:C.muted, fontSize:13, fontWeight:600, fontFamily:\"inherit\", cursor:\"pointer\" }}>\n                Try again\n              </button>\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        @keyframes spin{to{transform:rotate(360deg)}}\n        @keyframes pulse{0%,100%{box-shadow:0 16px 56px rgba(107,53,232,0.5)}50%{box-shadow:0 16px 72px rgba(107,53,232,0.7)}}\n        @media(max-width:700px){ .biz-split{grid-template-columns:1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n"};
for(const[rel,c]of Object.entries(files)){const p=rel.split('/').join(path.sep);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');console.log('  ✓',rel.split('/').pop());}
try{execSync('git add .',{stdio:'inherit'});const st=execSync('git status --short',{encoding:'utf8'}).trim();if(st){execSync('git commit -m "fix: register feature routes in app.ts, revamp 3 feature pages"',{stdio:'inherit'});}execSync('git push origin main',{stdio:'inherit'});console.log('\n✅ Pushed! Render auto-redeploys.');process.chdir('frontend');execSync('vercel --prod --force --yes',{stdio:'inherit'});console.log('\n🚀 LIVE');}catch(e){console.log(e.message);}